// UOM Dynamic Filter Client Script for Sales Invoice
frappe.ui.form.on('Sales Invoice', {
    onload: function(frm) {
        frm.set_query('uom', 'items', function(doc, cdt, cdn) {
            var row = frappe.get_doc(cdt, cdn);
            if (row.item_code && row.allowed_uoms && row.allowed_uoms.length > 0) {
                return {
                    filters: [
                        ['UOM', 'name', 'in', row.allowed_uoms]
                    ]
                };
            }
            // Fallback: If not loaded yet, allow currently selected UOM
            if (row.uom) {
                return {
                    filters: [
                        ['UOM', 'name', 'in', [row.uom]]
                    ]
                };
            }
            return {};
        });
    },
    refresh: function(frm) {
        if (frm.doc.items) {
            frm.doc.items.forEach(row => {
                fetch_allowed_uoms(frm, row.doctype, row.name);
            });
        }
    }
});

frappe.ui.form.on('Sales Invoice Item', {
    item_code: function(frm, cdt, cdn) {
        fetch_allowed_uoms(frm, cdt, cdn);
    },
    items_add: function(frm, cdt, cdn) {
        var row = frappe.get_doc(cdt, cdn);
        row.allowed_uoms = [];
    }
});

function fetch_allowed_uoms(frm, cdt, cdn) {
    var row = frappe.get_doc(cdt, cdn);
    if (!row || !row.item_code) return;

    if (!frm.item_uoms_cache) {
        frm.item_uoms_cache = {};
    }

    if (frm.item_uoms_cache[row.item_code]) {
        row.allowed_uoms = frm.item_uoms_cache[row.item_code];
        frm.fields_dict['items'].grid.refresh();
        return;
    }

    frappe.db.get_doc('Item', row.item_code).then(item_doc => {
        var uoms = [];
        if (item_doc.stock_uom) {
            uoms.push(item_doc.stock_uom);
        }
        if (item_doc.uoms) {
            item_doc.uoms.forEach(u => {
                if (u.uom && uoms.indexOf(u.uom) === -1) {
                    uoms.push(u.uom);
                }
            });
        }
        if (item_doc.barcodes) {
            item_doc.barcodes.forEach(b => {
                if (b.uom && uoms.indexOf(b.uom) === -1) {
                    uoms.push(b.uom);
                }
            });
        }

        frm.item_uoms_cache[row.item_code] = uoms;
        row.allowed_uoms = uoms;
        frm.fields_dict['items'].grid.refresh();
    });
}

