frappe.ui.form.on('POS Profile', {
    refresh: function(frm) {
        if (frappe.session.user === 'Administrator') {
            frm.add_custom_button(__('Clear POS Cipher'), function() {
                frappe.confirm('Are you sure you want to clear the POS Cipher for this profile?', function() {
                    frappe.call({
                        method: 'managely_terminal.managely_terminal.api.electron.pos_profile.clear_pos_cipher',
                        args: {
                            pos_profile: frm.doc.name
                        },
                        callback: function(r) {
                            if (r.message && r.message.success) {
                                frappe.msgprint(__('POS Cipher cleared successfully.'));
                                frm.reload_doc();
                            } else if (r.message && r.message.error) {
                                frappe.msgprint({
                                    title: __('Error'),
                                    indicator: 'red',
                                    message: r.message.error
                                });
                            }
                        }
                    });
                });
            });
        }
    }
});
